package com.xuhang.mealops.inventory.domain;
import java.math.BigDecimal; import java.util.List; import com.xuhang.mealops.measurement.domain.Quantity;
public record InventoryConsumptionPlan(Quantity requested,List<InventoryConsumptionAllocation> allocations) { public InventoryConsumptionPlan { if(requested==null||requested.amount().signum()<=0||!requested.unit().isBaseUnit()) throw new InvalidInventoryBatchException("Invalid consumption plan"); allocations=List.copyOf(allocations); if(allocations.isEmpty()) throw new InsufficientInventoryException("No allocation"); BigDecimal sum=BigDecimal.ZERO; for(int i=0;i<allocations.size();i++){var a=allocations.get(i);if(a.position()!=i+1||!a.unit().equals(requested.unit().code()))throw new InvalidInventoryBatchException("Invalid allocation positions or unit");sum=sum.add(a.amount());} if(sum.compareTo(requested.amount())!=0)throw new InvalidInventoryBatchException("Allocation total does not match request"); } public BigDecimal amount(){return requested.amount();} }
